];

// Variant 1: transform_self() - Apply stored xform (in-place)
let mut surface1 = NurbsSurface::create(false, false, 3, 3, 4, 4, &points).unwrap();
surface1.xform = Xform::translation(0.0, 0.0, 1.0);
